    if (!player || !player.metaSlotId || typeof MetaRPG === 'undefined') return;
    if (Math.floor(safeNum(floor, 1)) !== 100) return;
    const lines = typeof floorStories !== 'undefined' && Array.isArray(floorStories.finalBossOpening)
